class EngineModule27:
    """Implementation of EngineModule27 supporting process(data) and get_status()."""

    def __init__(self):
        self._status = "ready"
        self._last_processed = None

    def process(self, data):
        """Processes the given data, updates internal state, and returns a result dict."""
        self._last_processed = data
        self._status = "success"
        return {"status": "success", "data": data}

    def get_status(self):
        """Returns the current status of the engine module."""
        return self._status
